def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_threat = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 300:
                rich_threat += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opponents:
        return float(min(budget, 8.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if tight_supply:
        urgency += 2
    elif supply <= 19:
        urgency += 1

    if desperate_count >= 2:
        urgency += 1

    if day >= 8 and hp < 8:
        urgency += 1

    if highest_prev >= 120:
        market_mode = 'very_high'
    elif highest_prev >= 85:
        market_mode = 'high'
    elif highest_prev >= 40:
        market_mode = 'medium'
    else:
        market_mode = 'low'

    if urgency >= 6:
        bid = 92.0 if market_mode in ('very_high', 'high') else 72.0
    elif urgency >= 4:
        bid = 62.0 if market_mode == 'very_high' else 48.0
    elif urgency >= 2:
        if loose_supply and market_mode in ('high', 'very_high'):
            bid = 12.0
        else:
            bid = 24.0 if market_mode in ('high', 'very_high') else 18.0
    else:
        if loose_supply:
            bid = 6.0
        elif market_mode in ('high', 'very_high'):
            bid = 10.0
        else:
            bid = 14.0

    if highest_prev > 0 and highest_prev < 35 and urgency >= 3:
        bid = max(bid, highest_prev + 2.5)

    if avg_prev > 90 and urgency <= 2:
        bid = min(bid, 14.0)

    reserve_days = max(0, 10 - int(day))
    soft_cap = budget
    if reserve_days > 0:
        keep_reserve = reserve_days * 8.0
        soft_cap = max(0.0, budget - keep_reserve)
        if urgency >= 5:
            soft_cap = budget

    if soft_cap <= 0:
        bid = min(bid, budget * 0.5)
    else:
        bid = min(bid, soft_cap)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, 95.0))

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = [o for o in opponents_status.values() if o.get('alive')]

    # Base safety: if we're in trouble, prioritize survival.
    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, DAILY_SALARY * 0.95)
        return float(bid)

    # Read yesterday bids for immediate opponent pressure.
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # If there was high bidding pressure yesterday, we match moderately.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If someone was bidding near salary, they likely continue to contest.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # Don't overpay; stay just below typical contest level.
            bid = min(budget, DAILY_SALARY * 0.65)
            return float(bid)
        # If bids were low, we can take supply with a mid bid.
        if highest_prev_bid <= DAILY_SALARY * 0.25:
            bid = min(budget, DAILY_SALARY * 0.45)
            return float(bid)

    # Otherwise, adapt to supply level: higher supply means we can bid less.
    # supply is within [15,25].
    # Map supply to a factor in [0.55..0.35].
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    t = max(0.0, min(1.0, float(t)))
    # More supply -> lower bid.
    factor = 0.55 - 0.20 * t
    bid = min(budget, DAILY_SALARY * factor)
    # Ensure at least a minimal competitive bid when budget allows.
    min_bid = min(budget, DAILY_SALARY * 0.30)
    if bid < min_bid:
        bid = min_bid
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_possible_winners = int(day_context['supply'] // WATER_REQ)
    if max_possible_winners == 0: 
        max_possible_winners = 1 

    num_competitors = len(alive_opponents)

    bid_factor = 0.55 
    bid_amount_from_prev = 0.0

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if max_possible_winners <= 1: 
            if my_status['hp'] <= 3: 
                bid_factor = 0.95
            else: 
                bid_factor = 0.80
            bid_amount_from_prev = highest_prev_bid + 5.0
        elif max_possible_winners >= num_competitors + 1: 
            bid_factor = 0.40
            bid_amount_from_prev = highest_prev_bid + 1.0
        else: 
            if my_status['hp'] <= 2: 
                bid_factor = 0.90
            elif my_status['hp'] <= 5: 
                bid_factor = 0.75
            else: 
                bid_factor = 0.65
            bid_amount_from_prev = highest_prev_bid + 2.0

        bid_amount = max(DAILY_SALARY * bid_factor, bid_amount_from_prev)
    else: 
        if my_status['hp'] <= 2:
            bid_factor = 0.9
        else:
            bid_factor = 0.55
        bid_amount = DAILY_SALARY * bid_factor

    if my_status['hp'] <= 1:
        bid_amount = DAILY_SALARY * 0.99
    elif my_status['hp'] <= 3:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.9)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] > 0:
        required_budget_for_survival = DAILY_SALARY * (remaining_days + 1)
        if my_status['budget'] >= required_budget_for_survival:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.85)
        elif my_status['hp'] <= 3: 
             bid_amount = max(bid_amount, DAILY_SALARY * 0.98)

    final_bid = min(bid_amount, my_status['budget'])

    return max(1.0, final_bid)
